import { Font, FontLoader } from 'three/examples/jsm/loaders/FontLoader.js'

/** Anton typeface for the extruded 3D title (generated by `npm run make:font`). */
const URL = '/fonts/anton.typeface.json'

let font: Font | null = null
let pending: Promise<Font | null> | null = null

export function loadTitleFont(): Promise<Font | null> {
  if (pending) return pending
  pending = fetch(URL)
    .then((r) => (r.ok ? r.json() : Promise.reject(new Error(`font ${r.status}`))))
    .then((json) => {
      font = new FontLoader().parse(json)
      return font
    })
    .catch(() => null)
  return pending
}

export const getTitleFont = () => font
